        APIResponse::UpdateResponse(update_resp) => update_resp.res is Ok,
        APIResponse::UpdateStatusResponse(update_status_resp) => update_status_resp.res is Ok,
        APIResponse::GetThenDeleteResponse(resp) => resp.res is Ok,
