        // and can be unmarshalled to T...
        &&& T::unmarshal(s.resources()[cr.object_ref()]) is Ok
        // and its spec is the same as cr.
        &&& T::unmarshal(s.resources()[cr.object_ref()])->Ok_0.spec() == cr.spec()
    }
