        filtered_pods: None,
    }
}

pub open spec fn reconcile_done(state: VReplicaSetReconcileState) -> bool {
    match state.reconcile_step {
        VReplicaSetRecStepView::Done => true,
        _ => false,
    }
}

pub open spec fn reconcile_error(state: VReplicaSetReconcileState) -> bool {
