            &&& (self.precondition)(input, s)
            &&& s_prime == (self.transition)(input, s).0
        }
    }

    pub open spec fn weak_fairness(self, input: Input) -> TempPred<State> {
        always(lift_state(self.pre(input))).leads_to(lift_action(self.forward(input)))
