            &&& self.controller_models.contains_key(input.0)
            &&& input.2 is Some
            &&& received_msg_destined_for(input.1, HostId::Controller(controller_id, input.2->0))
            &&& host_result.is_Enabled()
            &&& network_result.is_Enabled()
        }
