impl<State, MessageOps> NetworkStateMachine<State, MessageOps> {

    pub open spec fn next_result(self, msg_ops: MessageOps, s: State) -> ActionResult<State, ()> {
        if (self.deliver.precondition)(msg_ops, s) {
