            // Creation succeeds.
            (APIServerState {
                resources: s.resources.insert(created_obj.object_ref(), created_obj),
                uid_counter: s.uid_counter + 1,
                resource_version_counter: s.resource_version_counter + 1,
                ..s
            }, CreateResponse{res: Ok(created_obj)})
        }
    }
