                    kind: Self::kind(),
                    metadata: self.metadata(),
                    spec: Self::marshal_spec(self.spec()),
                    status: Self::marshal_status(self.status()),
                }
            }

            open spec fn unmarshal(obj: DynamicObjectView) -> Result<Self, UnmarshalError> {
