pub open spec fn at_vrs_step_with_vrs(vrs: VReplicaSetView, controller_id: int, step: VReplicaSetRecStepView) -> StatePred<ClusterState> {
    |s: ClusterState| {
        let triggering_cr = VReplicaSetView::unmarshal(s.ongoing_reconciles(controller_id)[vrs.object_ref()].triggering_cr).unwrap();
        let local_state = VReplicaSetReconcileState::unmarshal(s.ongoing_reconciles(controller_id)[vrs.object_ref()].local_state).unwrap();
        &&& s.ongoing_reconciles(controller_id).contains_key(vrs.object_ref())
        &&& VReplicaSetView::unmarshal(s.ongoing_reconciles(controller_id)[vrs.object_ref()].triggering_cr).is_ok()
        &&& VReplicaSetReconcileState::unmarshal(s.ongoing_reconciles(controller_id)[vrs.object_ref()].local_state).is_ok()
        &&& triggering_cr.object_ref() == vrs.object_ref()
        &&& triggering_cr.spec() == vrs.spec()
        &&& triggering_cr.metadata().uid == vrs.metadata().uid
        &&& local_state.reconcile_step == step
    }
}

pub open spec fn num_diff_pods_is(vrs: VReplicaSetView, diff: int) -> StatePred<ClusterState> {
    |s: ClusterState| {
        let pods = matching_pods(vrs, s.resources());
        &&& pods.len() - vrs.spec.replicas.unwrap_or(0) == diff
    }
}

pub open spec fn pending_req_in_flight_at_after_delete_pod_step(
    vrs: VReplicaSetView, controller_id: int, diff: nat
) -> StatePred<ClusterState> {
    |s: ClusterState| {
        let step = VReplicaSetRecStepView::AfterDeletePod(diff);
        let msg = s.ongoing_reconciles(controller_id)[vrs.object_ref()].pending_req_msg->0;
        &&& at_vrs_step_with_vrs(vrs, controller_id, step)(s)
        &&& Cluster::pending_req_msg_is(controller_id, s, vrs.object_ref(), msg)
        &&& s.in_flight().contains(msg)
        &&& msg.src == HostId::Controller(controller_id, vrs.object_ref())
        &&& req_msg_is_get_then_delete_matching_pod_req(vrs, controller_id, msg)(s)
    }
}

pub open spec fn resp_msg_is_the_in_flight_ok_resp_at_after_delete_pod_step(
    vrs: VReplicaSetView, controller_id: int, resp_msg: Message, diff: nat
) -> StatePred<ClusterState> {
    |s: ClusterState| {
        let step = VReplicaSetRecStepView::AfterDeletePod(diff);
        let msg = s.ongoing_reconciles(controller_id)[vrs.object_ref()].pending_req_msg->0;
        let request = msg.content.get_APIRequest_0();
        &&& at_vrs_step_with_vrs(vrs, controller_id, step)(s)
        &&& Cluster::has_pending_k8s_api_req_msg(controller_id, s, vrs.object_ref())
        &&& msg.src == HostId::Controller(controller_id, vrs.object_ref())
        &&& msg.dst == HostId::APIServer
        &&& msg.content.is_APIRequest()
        &&& request.is_GetThenDeleteRequest()
        &&& s.in_flight().contains(resp_msg)
        &&& resp_msg_matches_req_msg(resp_msg, msg)
        &&& resp_msg.content.get_get_then_delete_response().res is Ok
    }
}

pub open spec fn req_msg_is_get_then_delete_matching_pod_req(
    vrs: VReplicaSetView, controller_id: int, req_msg: Message,
) -> StatePred<ClusterState> {
    |s: ClusterState| {
        let request = req_msg.content.get_APIRequest_0();
        let key = request.get_GetThenDeleteRequest_0().key;
        let obj = s.resources()[key];
        let state = VReplicaSetReconcileState::unmarshal(s.ongoing_reconciles(controller_id)[vrs.object_ref()].local_state).unwrap();
        let filtered_pods = state.filtered_pods.unwrap();
        let filtered_pod_keys = filtered_pods.map_values(|p: PodView| p.object_ref());
        let diff = state.reconcile_step.get_AfterDeletePod_0();
        // Basic requirements.
        &&& req_msg.dst == HostId::APIServer
        &&& req_msg.content.is_APIRequest()
        &&& request.is_GetThenDeleteRequest()
        // We require the key we are deleting is a pod in etcd owned by vrs.
        &&& s.resources().contains_key(key)
        &&& matching_pods(vrs, s.resources()).contains(obj)
        // We further require that the attached owner reference is the vrs 
        // controller owner reference.
        &&& request.get_GetThenDeleteRequest_0().owner_ref
            == vrs.controller_owner_ref()
        // We further require that the key of the sent request is the last index of
        // filtered_pods.
        &&& key == filtered_pod_keys[diff as int]
    }
}

pub open spec fn filtered_pods_in_vrs_matching_pods(
    vrs: VReplicaSetView, controller_id: int,
) -> StatePred<ClusterState> {
    |s: ClusterState| {
        let state = VReplicaSetReconcileState::unmarshal(s.ongoing_reconciles(controller_id)[vrs.object_ref()].local_state).unwrap();
        let filtered_pods = state.filtered_pods.unwrap();
        let filtered_pod_keys = filtered_pods.map_values(|p: PodView| p.object_ref());
        let diff = state.reconcile_step.get_AfterDeletePod_0();
        &&& s.ongoing_reconciles(controller_id).contains_key(vrs.object_ref())
        &&& VReplicaSetReconcileState::unmarshal(s.ongoing_reconciles(controller_id)[vrs.object_ref()].local_state).is_ok()
        &&& state.reconcile_step.is_AfterDeletePod()
        &&& state.filtered_pods is Some
        &&& filtered_pod_keys.no_duplicates()
        &&& diff < filtered_pods.len()
        &&& forall |i| #![trigger state.filtered_pods.unwrap()[i]] 0 <= i < diff ==> {
            &&& s.resources().contains_key(filtered_pod_keys[i])
            &&& matching_pods(vrs, s.resources()).contains(s.resources()[filtered_pod_keys[i]])
            &&& PodView::unmarshal(s.resources()[filtered_pod_keys[i]])->Ok_0 == filtered_pods[i]
        }
    }
}


// File: controllers/vreplicaset_controller/trusted/liveness_theorem.rs
pub open spec fn matching_pods(vrs: VReplicaSetView, resources: StoredState) -> Set<DynamicObjectView> {
    resources.values().filter(|obj: DynamicObjectView| owned_selector_match_is(vrs, obj))
}

pub open spec fn owned_selector_match_is(vrs: VReplicaSetView, obj: DynamicObjectView) -> bool {
    &&& obj.kind == PodView::kind()
    &&& obj.metadata.namespace is Some
    &&& obj.metadata.namespace == vrs.metadata.namespace
    &&& obj.metadata.owner_references_contains(vrs.controller_owner_ref())
    &&& vrs.spec.selector.matches(obj.metadata.labels.unwrap_or(Map::empty()))
    &&& obj.metadata.deletion_timestamp is None
}


// File: controllers/vreplicaset_controller/trusted/rely_guarantee.rs
pub open spec fn vrs_rely_create_req(req: CreateRequest) -> StatePred<ClusterState> {
    |s: ClusterState| {
        req.obj.kind == Kind::PodKind ==> !{
            let owner_references = req.obj.metadata.owner_references->0;
            &&& req.obj.metadata.owner_references is Some
            &&& exists |vrs: VReplicaSetView| 
                #[trigger] owner_references.contains(vrs.controller_owner_ref())
        }
    }
}

pub open spec fn vrs_rely_update_req(req: UpdateRequest) -> StatePred<ClusterState> {
    |s: ClusterState| {
        req.obj.kind == Kind::PodKind ==>
            req.obj.metadata.resource_version is Some
            // Prevents 1): where other controllers update pods already owned
            // by a VReplicaSet.
            && !{
                let etcd_obj = s.resources()[req.key()];
                let owner_references = etcd_obj.metadata.owner_references->0;
                &&& s.resources().contains_key(req.key())
                &&& etcd_obj.metadata.resource_version is Some
                &&& etcd_obj.metadata.resource_version == req.obj.metadata.resource_version
                &&& etcd_obj.metadata.owner_references is Some
                &&& exists |vrs: VReplicaSetView| 
                    #[trigger] owner_references.contains(vrs.controller_owner_ref())
            }
            // Prevents 2): where other controllers update pods so they become
            // owned by a VReplicaSet.
            && (req.obj.metadata.owner_references is Some ==>
                    forall |vrs: VReplicaSetView| 
                        ! #[trigger] req.obj.metadata.owner_references->0.contains(vrs.controller_owner_ref()))
    }
}

pub open spec fn vrs_rely_get_then_update_req(req: GetThenUpdateRequest) -> StatePred<ClusterState> {
    |s: ClusterState| {
        req.obj.kind == Kind::PodKind ==> {
            // Prevents 1): where other controllers update pods owned by a VReplicaSet.
            // an object can has multiple owners, but only one controller owner
            // We force requests from other controllers to carry the controller owner reference
            // to achieve exclusive ownerships
            // TODO: add type invariant
            &&& req.owner_ref.controller is Some
            &&& req.owner_ref.controller->0
            &&& req.owner_ref.kind != VReplicaSetView::kind()
            // Prevents 2): where other controllers update pods so they become
            // owned by a VReplicaSet.
            &&& (req.obj.metadata.owner_references is Some ==>
                forall |vrs: VReplicaSetView| 
                    ! req.obj.metadata.owner_references->0.contains(#[trigger] vrs.controller_owner_ref()))
        }
    }
}

pub open spec fn vrs_rely_update_status_req(req: UpdateStatusRequest) -> StatePred<ClusterState> {
    |s: ClusterState| {
        req.obj.kind == Kind::PodKind ==> 
            req.obj.metadata.resource_version is Some
            && !{
                let etcd_obj = s.resources()[req.key()];
                let owner_references = etcd_obj.metadata.owner_references->0;
                &&& s.resources().contains_key(req.key())
                &&& etcd_obj.metadata.resource_version is Some
                &&& etcd_obj.metadata.resource_version == req.obj.metadata.resource_version
                &&& etcd_obj.metadata.owner_references is Some
                &&& exists |vrs: VReplicaSetView| 
                    #[trigger] owner_references.contains(vrs.controller_owner_ref())
            }
    }
}

pub open spec fn vrs_rely_delete_req(req: DeleteRequest) -> StatePred<ClusterState> {
    |s: ClusterState| {
        req.key.kind == Kind::PodKind ==>
            req.preconditions is Some
            && req.preconditions->0.resource_version is Some
            && !{
                let etcd_obj = s.resources()[req.key];
                let owner_references = etcd_obj.metadata.owner_references->0;
                &&& s.resources().contains_key(req.key)
                &&& etcd_obj.metadata.resource_version is Some
                &&& etcd_obj.metadata.resource_version
                    == req.preconditions->0.resource_version
                &&& etcd_obj.metadata.owner_references is Some
                &&& exists |vrs: VReplicaSetView| 
                    #[trigger] owner_references.contains(vrs.controller_owner_ref())
            }
    }
}

pub open spec fn vrs_rely_get_then_delete_req(req: GetThenDeleteRequest) -> StatePred<ClusterState> {
    |s: ClusterState| {
        req.key.kind == Kind::PodKind ==> {
            &&& req.owner_ref.controller is Some
            &&& req.owner_ref.controller->0
            &&& req.owner_ref.kind != VReplicaSetView::kind()
        }
    }
}

pub open spec fn vrs_rely(other_id: int) -> StatePred<ClusterState> {
    |s: ClusterState| {
        forall |msg| {
            &&& #[trigger] s.in_flight().contains(msg)
            &&& msg.content.is_APIRequest()
            &&& msg.src.is_controller_id(other_id)
        } ==> match msg.content.get_APIRequest_0() {
            APIRequest::CreateRequest(req) => vrs_rely_create_req(req)(s),
            APIRequest::UpdateRequest(req) => vrs_rely_update_req(req)(s),
            APIRequest::GetThenUpdateRequest(req) => vrs_rely_get_then_update_req(req)(s),
            APIRequest::UpdateStatusRequest(req) => vrs_rely_update_status_req(req)(s),
            APIRequest::DeleteRequest(req) => vrs_rely_delete_req(req)(s),
            APIRequest::GetThenDeleteRequest(req) => vrs_rely_get_then_delete_req(req)(s),
            _ => true,
        }
    }
}


#[macro_export]
macro_rules! combine_spec_entails_always_n {
    [$($tail:tt)*] => {
        verus_proof_macro_exprs!(combine_spec_entails_always_n_internal!($($tail)*))
    }
}

#[macro_export]
macro_rules! combine_spec_entails_always_n_internal {
    ($spec:expr, $partial_spec:expr, $($tail:tt)*) => {
        assert_by(
            valid($spec.implies(always(combine_with_next!($($tail)*)))),
            {
                entails_always_and_n!($spec, $($tail)*);
            }
        );
        entails_preserved_by_always(combine_with_next!($($tail)*), $partial_spec);
        entails_trans($spec, always(combine_with_next!($($tail)*)), always($partial_spec));
    };
}

#[macro_export]
macro_rules! entails_always_and_n {
    [$($tail:tt)*] => {
        verus_proof_macro_exprs!(entails_always_and_n_internal!($($tail)*));
    };
}

#[macro_export]
macro_rules! entails_always_and_n_internal {
    ($spec:expr, $p1:expr) => {};
    ($spec:expr, $p1:expr, $p2:expr) => {
        entails_and_temp($spec, always($p1), always($p2));
        always_and_equality($p1, $p2);
    };
    ($spec:expr, $p1:expr, $p2:expr, $($tail:tt)*) => {
        entails_and_temp($spec, always($p1), always($p2));
        always_and_equality($p1, $p2);
        entails_always_and_n_internal!($spec, $p1.and($p2), $($tail)*);
    };
}

#[macro_export]
macro_rules! combine_with_next {
    [$($tail:tt)*] => {
        verus_proof_macro_exprs!(combine_with_next_internal!($($tail)*))
    }
}

#[macro_export]
macro_rules! combine_with_next_internal {
    ($next:expr) => {
        $next
    };
    ($next:expr, $($expr:expr),* $(,)?) => {
        $next $(
            .and($expr)
        )*
    };
}

