    |s: ClusterState| {
        (req.key.kind == Kind::PodKind
            && req.key.namespace == vrs.metadata.namespace.unwrap()) ==> {
            &&& req.owner_ref.controller is Some
            &&& req.owner_ref.controller->0
            &&& req.owner_ref != vrs.controller_owner_ref()
