                &&& self.controller_models.contains_key(controller_id)
                &&& input.1 is Some
                &&& received_msg_destined_for(input.0, HostId::Controller(controller_id, input.1->0))
                &&& result(input, s).0.is_Enabled()
                &&& result(input, s).1.is_Enabled()
