    pub transition: spec_fn(Input, State) -> (State, Output),
}

impl<State, Input, Output> Action<State, Input, Output> {

    pub open spec fn pre(self, input: Input) -> StatePred<State> {
        |s: State| (self.precondition)(input, s)
