pub open spec fn controller(model: ReconcileModel, controller_id: int) -> ControllerStateMachine {
    StateMachine {
        init: |s: ControllerState| {
            s == ControllerState {
                scheduled_reconciles: Map::<ObjectRef, DynamicObjectView>::empty(),
