        s2.inv(c),
        os::step_MemOp(c, s1, s2, core, lbl),
        s1.sound,
    ensures
        ({
            let vaddr = lbl->MemOp_vaddr;
            let op = lbl->MemOp_op;
            let mlbl = crate::Lbl::MemOp(core, vaddr as usize, op);
            let mmu_step = choose|step| crate::rl1::next_step(s1.mmu@, s2.mmu@, c.common, step, mlbl);
            match mmu_step {
                crate::rl1::Step::MemOpNoTr =>
                    hlspec::step_MemOp(c.interp(), s1.interp(c), s2.interp(c), None, lbl),
                crate::rl1::Step::MemOpNoTrNA { .. } =>
