    pub open spec fn inv_mapping__inflight_walks(self, c: Constants) -> bool {
        forall|core, walk| c.valid_core(core) && #[trigger] self.walks[core].contains(walk) ==> {
            &&& walk.vaddr < MAX_BASE
            &&& aligned(walk.vaddr as nat, 8)
            &&& walk.path.len() <= 3
