    &&& post.os_ext.allocated    == pre.os_ext.allocated
    &&& post.mmu@.writes.tso.subset_of(pre.mmu@.writes.tso)
    &&& post.mmu@.writes.nonpos.subset_of(pre.mmu@.writes.nonpos)
