                    && self.page_io_mappings(p) =~= old(self).page_io_mappings(p),
            ret.0 == ret.1@.addr(),
            ret.1@.is_init(),
    {
        let ret = self.free_pages_2m.pop().0;
        self.set_state(page_ptr2page_index(ret), PageState::Allocated2m);
