            0 <= l3i < 512,
    {
        if self.spec_resolve_mapping_l4(l4i).is_none() {
            None
        } else if !self.l3_tables@[self.spec_resolve_mapping_l4(
            l4i,
        )->0.addr].value()[l3i].perm.present
            || !self.l3_tables@[self.spec_resolve_mapping_l4(
            l4i,
        )->0.addr].value()[l3i].perm.ps {
