        pub mem_2m:usize,
        pub mem_1g:usize,
        pub pcid:usize,
        pub ioid:usize,
    }

    impl Quota{

        pub open spec fn spec_set_mem_4k(&self, v:usize) -> Self
        {
            Self{
                mem_4k:v,
                mem_2m:self.mem_2m,
                mem_1g:self.mem_1g,
                pcid:self.pcid,
                ioid:self.ioid,
            }
        }

        pub open spec fn spec_subtract_mem_4k(&self, new:Self, k:usize) -> bool
        {
           &&&
           self.mem_4k - k == new.mem_4k
           &&&
           self.mem_2m == new.mem_2m
           &&&
           self.mem_1g == new.mem_1g
           &&&
           self.pcid == new.pcid
           &&&
           self.ioid == new.ioid
        }

}



