    container_ptr: ContainerPtr,
)
    requires
        remove_container_ensures(
            root_container,
            old_container_perms,
            new_container_perms,
            container_ptr,
        ),
    ensures
        container_childern_parent_wf(
            root_container,
            new_container_perms,
        ),

{
}

}

