            IPCPayLoad::Empty,
            None,
        );
        thread_set_current_cpu(thread_ptr, &mut thread_perm, Some(cpu_id));

        self.cpu_list.set(
            cpu_id,
            Cpu {
                owning_container: old_cpu.owning_container,
                active: old_cpu.active,
                current_thread: Some(thread_ptr),
