    pub fn schedule_blocked_thread(&mut self, endpoint_ptr: EndpointPtr)
        requires
            old(self).wf(),
            old(self).endpoint_dom().contains(endpoint_ptr),
            old(self).get_endpoint(endpoint_ptr).queue.len() > 0,
            old(self).get_container(
                old(self).get_thread(
